head.b:skin:
/* -------------------------------------------------------------------------
   MRS DIGITAL - UNIVERSAL MULTI-DEVICE RESPONSIVE THEME
   Tailored for: Android, iPhone, iPad, Foldables, Laptops & High-Res Desktops
   ------------------------------------------------------------------------- */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  -webkit-tap-highlight-color: transparent;
}
:root {
  --bg-slate-50: #f8fafc;
  --bg-slate-100: #f1f5f9;
  --bg-slate-800: #1e293b;
  --bg-slate-900: #0f172a;
  --bg-slate-950: #020617;
  --text-dark: #0f172a;
  --text-muted: #64748b;
  --amber-500: #f59e0b;
  --amber-400: #fbbf24;
  --amber-600: #d97706;
  --emerald-500: #10b981;
  --emerald-600: #059669;
  --rose-500: #f43f5e;
  --border-color: #e2e8f0;
  --border-dark: #1e293b;
  --font-sans: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
  --font-mono: 'JetBrains Mono', Menlo, Monaco, Consolas, monospace;
  --sat: env(safe-area-inset-top, 0px);
  --sab: env(safe-area-inset-bottom, 0px);
  --sal: env(safe-area-inset-left, 0px);
  --sar: env(safe-area-inset-right, 0px);
}
html {
  width: 100% !important;
  max-width: 100% !important;
  overflow-x: hidden !important;
  -webkit-text-size-adjust: 100%;
  -ms-text-size-adjust: 100%;
}
body {
  width: 100% !important;
  max-width: 100% !important;
  min-height: 100%;
  overflow-x: hidden !important;
  position: relative;
  background-color: var(--bg-slate-50);
  color: var(--text-dark);
  font-family: var(--font-sans);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}
img, video, canvas, audio {
  max-width: 100%;
  height: auto;
}
iframe {
  max-width: 100%;
}
a {
  color: inherit;
  text-decoration: none;
}
button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
  touch-action: manipulation;
}

/* Container System: Fluid for all widths */
.container {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding-left: max(16px, var(--sal));
  padding-right: max(16px, var(--sar));
}
@media (max-width: 640px) {
  .container {
    padding-left: max(12px, var(--sal));
    padding-right: max(12px, var(--sar));
  }
}

/* Top Announcement Bar */
.top-bar {
  background-color: var(--bg-slate-900);
  color: #cbd5e1;
  font-size: 11px;
  padding-top: max(6px, var(--sat));
  padding-bottom: 6px;
  border-bottom: 1px solid var(--border-dark);
}
.top-bar-inner {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}
.top-charity-badge {
  display: flex;
  align-items: center;
  gap: 6px;
  font-weight: 700;
  color: #fb7185;
  font-size: 11px;
}
.top-links {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}
.top-partner-btn {
  background: var(--amber-500);
  color: #020617;
  font-weight: 800;
  padding: 4px 10px;
  border-radius: 6px;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 11px;
  min-height: 28px;
  transition: background 0.2s;
}
.top-partner-btn:hover {
  background: var(--amber-400);
}

/* Header Nav */
.site-header {
  background: rgba(255, 255, 255, 0.98);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--border-color);
  position: sticky;
  top: 0;
  z-index: 50;
  width: 100%;
}
.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 60px;
}
.brand-logo {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: clamp(16px, 4vw, 19px);
  font-weight: 800;
  letter-spacing: -0.02em;
  color: var(--bg-slate-900);
}
.brand-tag {
  background: #fef3c7;
  color: #78350f;
  font-size: 10px;
  font-weight: 800;
  padding: 2px 6px;
  border-radius: 5px;
  border: 1px solid #fde68a;
}
.nav-menu {
  display: flex;
  align-items: center;
  gap: 16px;
  font-size: 13px;
  font-weight: 600;
  color: #475569;
}
.nav-menu a:hover {
  color: var(--bg-slate-900);
}
.header-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}
.header-store-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 14px;
  border-radius: 10px;
  background: #ff9900;
  color: #111111;
  font-weight: 800;
  font-size: 12px;
  min-height: 38px;
  transition: all 0.2s;
  box-shadow: 0 2px 8px rgba(255, 153, 0, 0.25);
}
.header-store-btn:hover {
  background: #e68a00;
  color: #000000;
}
.charity-nav-btn {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 6px 10px;
  border-radius: 8px;
  background: #fff1f2;
  color: #9f1239;
  border: 1px solid #fecdd3;
  font-weight: 700;
  font-size: 11px;
  min-height: 28px;
}
.hamburger-btn {
  display: none;
  font-size: 20px;
  padding: 8px 12px;
  border-radius: 8px;
  background: var(--bg-slate-100);
  color: var(--bg-slate-900);
  min-height: 40px;
  min-width: 44px;
}

@media (max-width: 900px) {
  .nav-menu {
    display: none;
  }
  .hamburger-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
  }
}

/* Mobile Drawer Menu */
.mobile-drawer {
  position: fixed;
  top: 0;
  right: -320px;
  width: min(85vw, 320px);
  height: 100%;
  background: #ffffff;
  box-shadow: -5px 0 30px rgba(0,0,0,0.25);
  z-index: 1000;
  transition: right 0.3s cubic-bezier(0.16, 1, 0.3, 1);
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 14px;
  overflow-y: auto;
}
.mobile-drawer.open {
  right: 0;
}
.drawer-overlay {
  position: fixed;
  inset: 0;
  background: rgba(15, 23, 42, 0.65);
  backdrop-filter: blur(3px);
  z-index: 999;
  display: none;
}
.drawer-overlay.open {
  display: block;
}
.drawer-close {
  align-self: flex-end;
  font-size: 22px;
  color: #64748b;
  padding: 6px 10px;
  min-height: 44px;
  min-width: 44px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.drawer-links a, .drawer-links button {
  display: flex;
  align-items: center;
  width: 100%;
  text-align: left;
  padding: 12px 6px;
  min-height: 44px;
  font-size: 14px;
  font-weight: 700;
  color: var(--bg-slate-900);
  border-bottom: 1px solid var(--border-color);
}

/* Hero Section */
.hero-section {
  background: radial-gradient(circle at top right, #1e293b 0%, #0f172a 100%);
  color: #ffffff;
  padding: clamp(28px, 6vw, 48px) 0;
  position: relative;
}
.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 10px;
  border-radius: 9999px;
  background: rgba(245, 158, 11, 0.15);
  border: 1px solid rgba(245, 158, 11, 0.4);
  color: #fde68a;
  font-size: 11px;
  font-weight: 700;
  margin-bottom: 12px;
}
.hero-title {
  font-size: clamp(22px, 5vw, 36px);
  font-weight: 800;
  line-height: 1.25;
  letter-spacing: -0.03em;
  max-width: 840px;
  margin-bottom: 10px;
}
.hero-desc {
  font-size: clamp(13px, 2.8vw, 15px);
  color: #94a3b8;
  max-width: 680px;
  line-height: 1.6;
  margin-bottom: 20px;
}
.hero-actions {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  margin-bottom: 22px;
}
.btn-primary {
  background: var(--amber-500);
  color: #020617;
  font-weight: 800;
  font-size: 13px;
  padding: 10px 18px;
  border-radius: 10px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 44px;
  gap: 6px;
  box-shadow: 0 4px 12px rgba(245, 158, 11, 0.3);
  transition: all 0.2s;
}
.btn-primary:hover {
  background: var(--amber-400);
}
.btn-secondary {
  background: rgba(255, 255, 255, 0.12);
  color: #ffffff;
  font-weight: 700;
  font-size: 13px;
  padding: 10px 16px;
  border-radius: 10px;
  border: 1px solid rgba(255, 255, 255, 0.25);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 44px;
  transition: all 0.2s;
}
.btn-amazon {
  background: #ff9900;
  color: #111111;
  font-weight: 800;
  font-size: 13px;
  padding: 10px 18px;
  border-radius: 10px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 44px;
  gap: 6px;
  box-shadow: 0 4px 12px rgba(255, 153, 0, 0.3);
  transition: all 0.2s;
}
.btn-amazon:hover {
  background: #e68a00;
  color: #000000;
}
.btn-shopz {
  background: #10b981;
  color: #ffffff;
  font-weight: 800;
  font-size: 13px;
  padding: 10px 18px;
  border-radius: 10px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 44px;
  gap: 6px;
  box-shadow: 0 4px 12px rgba(16, 185, 129, 0.3);
  transition: all 0.2s;
}
.btn-shopz:hover {
  background: #059669;
  color: #ffffff;
}

/* Charity Pledge Banner */
.charity-pledge-card {
  background: rgba(15, 23, 42, 0.75);
  border: 1px solid rgba(244, 63, 94, 0.35);
  border-radius: 12px;
  padding: 12px 14px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 10px;
  max-width: 780px;
}
.pledge-left {
  display: flex;
  align-items: center;
  gap: 10px;
}
.pledge-icon {
  width: 32px;
  height: 32px;
  border-radius: 8px;
  background: rgba(244, 63, 94, 0.15);
  color: #fb7185;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
  flex-shrink: 0;
}
.pledge-text h4 {
  font-size: 12px;
  font-weight: 700;
  color: #ffffff;
}
.pledge-text p {
  font-size: 11px;
  color: #94a3b8;
}
.pledge-btn {
  background: #f43f5e;
  color: #ffffff;
  font-weight: 700;
  font-size: 11px;
  padding: 8px 14px;
  border-radius: 8px;
  min-height: 36px;
  transition: background 0.2s;
}

/* AUTOMATIC SYSTEM: VISITOR'S CHOICE AUTO-INCLUSION */
.auto-engine-card {
  background: linear-gradient(135deg, #0f172a 0%, #1e1b4b 100%);
  border: 1px solid #334155;
  border-radius: 16px;
  padding: clamp(14px, 3vw, 20px);
  color: #ffffff;
  margin-bottom: 24px;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.15);
}
.engine-head {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin-bottom: 12px;
}
.engine-tag {
  font-size: 10px;
  font-weight: 800;
  color: #fbbf24;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}
.engine-title {
  font-size: clamp(15px, 3.5vw, 18px);
  font-weight: 800;
  color: #ffffff;
}
.engine-sub {
  font-size: 11px;
  color: #cbd5e1;
}
.engine-form {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin-bottom: 12px;
}
.engine-input {
  flex: 1;
  min-width: 200px;
  background: #020617;
  border: 1px solid #475569;
  color: #ffffff;
  font-size: 12px;
  padding: 10px 12px;
  min-height: 44px;
  border-radius: 10px;
  outline: none;
}
.engine-input:focus {
  border-color: #fbbf24;
}
.engine-select {
  background: #1e293b;
  border: 1px solid #475569;
  color: #ffffff;
  font-size: 12px;
  font-weight: 700;
  padding: 10px 12px;
  min-height: 44px;
  border-radius: 10px;
  outline: none;
}
.engine-btn {
  background: #f59e0b;
  color: #020617;
  font-size: 12px;
  font-weight: 800;
  padding: 10px 16px;
  min-height: 44px;
  border-radius: 10px;
  transition: background 0.2s;
  white-space: nowrap;
}
@media (max-width: 600px) {
  .engine-form {
    flex-direction: column;
  }
  .engine-input, .engine-select, .engine-btn {
    width: 100%;
    min-width: 100%;
  }
}
.chips-bar {
  display: flex;
  align-items: center;
  gap: 6px;
  overflow-x: auto;
  padding-top: 8px;
  border-top: 1px solid #334155;
  scrollbar-width: none;
  -webkit-overflow-scrolling: touch;
}
.chips-bar::-webkit-scrollbar {
  display: none;
}
.chips-label {
  font-size: 10px;
  font-weight: 700;
  color: #94a3b8;
  white-space: nowrap;
}
.choice-chip {
  background: rgba(255, 255, 255, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.2);
  color: #e2e8f0;
  font-size: 11px;
  padding: 6px 12px;
  min-height: 32px;
  border-radius: 8px;
  white-space: nowrap;
  transition: all 0.2s;
}
.choice-chip:hover {
  background: rgba(255, 255, 255, 0.2);
  color: #ffffff;
}

/* Store Section */
.store-section {
  padding: clamp(24px, 5vw, 40px) 0;
}
.section-head {
  margin-bottom: 18px;
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  flex-wrap: wrap;
  gap: 10px;
}
.section-tag {
  font-size: 10px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--amber-600);
  margin-bottom: 2px;
}
.section-title {
  font-size: clamp(19px, 4vw, 26px);
  font-weight: 800;
  color: var(--bg-slate-900);
  letter-spacing: -0.02em;
}

/* Department Filter Tabs (Finger Swipe Optimized) */
.filter-tabs {
  display: flex;
  align-items: center;
  gap: 6px;
  overflow-x: auto;
  padding-bottom: 8px;
  margin-bottom: 18px;
  scrollbar-width: none;
  -webkit-overflow-scrolling: touch;
}
.filter-tabs::-webkit-scrollbar {
  display: none;
}
.tab-btn {
  padding: 8px 14px;
  min-height: 36px;
  border-radius: 9px;
  font-size: 12px;
  font-weight: 700;
  background: #ffffff;
  color: #475569;
  border: 1px solid var(--border-color);
  white-space: nowrap;
  transition: all 0.2s;
}
.tab-btn.active, .tab-btn:hover {
  background: var(--bg-slate-900);
  color: #ffffff;
  border-color: var(--bg-slate-900);
}
.tab-btn.shopz-tab {
  background: #ecfdf5;
  color: #065f46;
  border-color: #a7f3d0;
}
.tab-btn.shopz-tab.active {
  background: var(--emerald-600);
  color: #ffffff;
  border-color: var(--emerald-600);
}

/* Main Grid Layout with Products + Sidebar */
.content-with-sidebar {
  display: grid;
  grid-template-columns: 1fr 300px;
  gap: 20px;
  margin-bottom: 30px;
}
@media (max-width: 992px) {
  .content-with-sidebar {
    grid-template-columns: 1fr;
  }
}

/* Product Grid: Adaptive from 1 column to multiple */
.product-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(230px, 1fr));
  gap: 16px;
}
@media (max-width: 640px) {
  .product-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 10px;
  }
  .product-card {
    padding: 10px 8px;
    border-radius: 12px;
  }
  .product-img-box {
    height: clamp(120px, 32vw, 150px) !important;
    margin-bottom: 8px;
  }
  .product-title {
    font-size: 12px !important;
    line-height: 1.3 !important;
    margin-bottom: 4px !important;
    -webkit-line-clamp: 2 !important;
  }
  .product-rating {
    font-size: 10px !important;
    margin-bottom: 6px !important;
  }
  .product-bottom {
    flex-direction: column !important;
    align-items: stretch !important;
    gap: 6px !important;
    padding-top: 6px !important;
  }
  .product-price {
    font-size: 15px !important;
  }
  .btn-buy-amazon, .btn-buy-shopz {
    width: 100% !important;
    font-size: 11px !important;
    padding: 7px 6px !important;
    min-height: 36px !important;
  }
}
@media (max-width: 320px) {
  .product-grid {
    grid-template-columns: 1fr;
    gap: 10px;
  }
}

.product-card {
  background: #ffffff;
  border: 1px solid var(--border-color);
  border-radius: 14px;
  padding: 12px;
  display: flex;
  flex-direction: column;
  transition: transform 0.2s, box-shadow 0.2s;
  position: relative;
}
.product-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 20px -4px rgba(0, 0, 0, 0.08);
}
.product-img-box {
  width: 100%;
  height: 180px;
  background: #f1f5f9;
  border-radius: 10px;
  overflow: hidden;
  margin-bottom: 10px;
  position: relative;
}
.product-img-box img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.prime-badge {
  position: absolute;
  top: 8px;
  left: 8px;
  background: #0284c7;
  color: #ffffff;
  font-size: 9px;
  font-weight: 800;
  padding: 2px 7px;
  border-radius: 5px;
  letter-spacing: 0.02em;
}
.shopz-badge {
  position: absolute;
  top: 8px;
  left: 8px;
  background: #059669;
  color: #ffffff;
  font-size: 9px;
  font-weight: 800;
  padding: 2px 7px;
  border-radius: 5px;
  letter-spacing: 0.02em;
}
.product-category {
  font-size: 10px;
  font-weight: 800;
  color: var(--amber-600);
  text-transform: uppercase;
  margin-bottom: 3px;
}
.product-title {
  font-size: 14px;
  font-weight: 700;
  color: var(--bg-slate-900);
  line-height: 1.35;
  margin-bottom: 6px;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.product-rating {
  font-size: 11px;
  font-weight: 600;
  color: #f59e0b;
  margin-bottom: 8px;
}
.product-bottom {
  margin-top: auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 10px;
  border-top: 1px solid #f1f5f9;
  gap: 8px;
}
.product-price {
  font-size: 17px;
  font-weight: 800;
  color: var(--bg-slate-900);
}
.btn-buy-amazon {
  background: #ff9900;
  color: #111111;
  font-weight: 800;
  font-size: 11px;
  padding: 8px 14px;
  min-height: 38px;
  border-radius: 8px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  transition: background 0.2s;
  white-space: nowrap;
}
.btn-buy-amazon:hover {
  background: #e68a00;
}
.btn-buy-shopz {
  background: #10b981;
  color: #ffffff;
  font-weight: 800;
  font-size: 11px;
  padding: 8px 14px;
  min-height: 38px;
  border-radius: 8px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  transition: background 0.2s;
  white-space: nowrap;
}
.btn-buy-shopz:hover {
  background: #059669;
}

/* Sidebar Widgets & Ad Scaling */
.sidebar-widget {
  background: #ffffff;
  border: 1px solid var(--border-color);
  border-radius: 14px;
  padding: 14px;
  margin-bottom: 18px;
  overflow: hidden !important;
  contain: layout paint;
}
.sidebar-widget-title {
  font-size: 13px;
  font-weight: 800;
  color: var(--bg-slate-900);
  margin-bottom: 10px;
  padding-bottom: 6px;
  border-bottom: 1px solid var(--border-color);
}

@media (max-width: 768px) {
  .sidebar-widget {
    padding: 10px 8px;
  }
}



/* Fixed Bottom Nav Bar for Android & Mobile Phones with Safe Area */
.mobile-bottom-nav {
  display: none;
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  height: calc(56px + var(--sab));
  background: rgba(255, 255, 255, 0.98);
  backdrop-filter: blur(10px);
  border-top: 1px solid var(--border-color);
  z-index: 90;
  justify-content: space-around;
  align-items: flex-start;
  padding: 6px 4px var(--sab) 4px;
  box-shadow: 0 -3px 12px rgba(0,0,0,0.06);
}
@media (max-width: 768px) {
  .mobile-bottom-nav {
    display: flex;
  }
  body {
    padding-bottom: calc(66px + var(--sab));
  }
}
.mob-nav-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  font-size: 10px;
  font-weight: 700;
  color: #64748b;
  gap: 2px;
  min-height: 44px;
  min-width: 44px;
  padding: 0 4px;
  flex: 1;
}
.mob-nav-item.active {
  color: var(--amber-600);
}

/* Charity Modal */
.modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(15, 23, 42, 0.75);
  backdrop-filter: blur(4px);
  z-index: 2000;
  display: none;
  align-items: center;
  justify-content: center;
  padding: 12px;
}
.modal-overlay.open {
  display: flex;
}
.modal-box {
  background: #ffffff;
  border-radius: 16px;
  max-width: 520px;
  width: 100%;
  padding: 18px;
  max-height: 85vh;
  overflow-y: auto;
}
@media (max-width: 640px) {
  .modal-box {
    max-height: 85dvh;
    width: 100%;
    border-radius: 16px 16px 0 0;
    position: fixed;
    bottom: 0;
    padding-bottom: max(18px, var(--sab));
  }
}
.modal-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 12px;
}
.cause-card {
  border: 2px solid var(--border-color);
  border-radius: 10px;
  padding: 10px 12px;
  margin-bottom: 8px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 12px;
  min-height: 44px;
}
.cause-card.selected {
  border-color: #f43f5e;
  background: #fff1f2;
}

/* Footer */
.site-footer {
  background: var(--bg-slate-950);
  color: #94a3b8;
  font-size: 12px;
  padding: 36px 0 20px;
  border-top: 1px solid var(--border-dark);
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 20px;
  margin-bottom: 26px;
  padding-bottom: 20px;
  border-bottom: 1px solid var(--border-dark);
}
.b-section-wrap {
  margin-top: 20px;
}

body.script:
//
  // Mobile Drawer
  function toggleDrawer() {
    var d = document.getElementById('mobileDrawer');
    var o = document.getElementById('drawerOverlay');
    if (!d || !o) return;
    d.classList.toggle('open');
    o.classList.toggle('open');
  }

  // Charity Modal
  function openCharityModal() {
    var m = document.getElementById('charityModal');
    if (m) m.classList.add('open');
  }
  function closeCharityModal() {
    var m = document.getElementById('charityModal');
    if (m) m.classList.remove('open');
  }
  function selectCause(name, cardId) {
    document.querySelectorAll('.cause-card').forEach(function(c) {
      c.classList.remove('selected');
      var chk = c.querySelector('div:last-child');
      if (chk && chk.textContent === '✓') chk.remove();
    });
    var card = document.getElementById(cardId);
    if (card) {
      card.classList.add('selected');
      var tick = document.createElement('div');
      tick.style.color = '#f43f5e';
      tick.style.fontWeight = '800';
      tick.textContent = '✓';
      card.appendChild(tick);
    }
    var sub = document.getElementById('heroPledgeSub');
    if (sub) {
      sub.textContent = '5% of all affiliate earnings are pledged to ' + name + ' at zero extra cost to you.';
    }
  }

  // Category Filter Tabs
  function filterProducts(cat) {
    var cards = document.querySelectorAll('#productContainer .product-card');
    var buttons = document.querySelectorAll('.filter-tabs .tab-btn');
    buttons.forEach(function(b) { b.classList.remove('active'); });
    if (window.event && window.event.target) {
      window.event.target.classList.add('active');
    }

    cards.forEach(function(card) {
      if (cat === 'all') {
        card.style.display = 'flex';
      } else {
        var itemCat = card.getAttribute('data-cat') || '';
        if (itemCat.indexOf(cat) !== -1) {
          card.style.display = 'flex';
        } else {
          card.style.display = 'none';
        }
      }
    });
  }



  // AUTOMATIC SYSTEM: VISITOR'S CHOICE AUTO-INCLUSION
  var imageCatalog = {
    earbuds: 'https://images.unsplash.com/photo-1590658268037-6bf12165a8df?w=800&auto=format&fit=crop&q=80',
    keyboard: 'https://images.unsplash.com/photo-1587829741301-dc798b83add3?w=800&auto=format&fit=crop&q=80',
    watch: 'https://images.unsplash.com/photo-1523275335684-37898b6baf30?w=800&auto=format&fit=crop&q=80',
    monitor: 'https://images.unsplash.com/photo-1527443224154-c4a3942d3acf?w=800&auto=format&fit=crop&q=80',
    power: 'https://images.unsplash.com/photo-1583863788434-e58a36330cf0?w=800&auto=format&fit=crop&q=80',
    speaker: 'https://images.unsplash.com/photo-1545454675-3531b543be5d?w=800&auto=format&fit=crop&q=80',
    default: 'https://images.unsplash.com/photo-1505740420928-5e560c06d30e?w=800&auto=format&fit=crop&q=80'
  };

  function autoIncludeVisitorChoice() {
    var input = document.getElementById('visitorChoiceInput');
    var keyword = input ? input.value.trim() : '';
    var platformSelect = document.getElementById('visitorPlatformSelect');
    var platform = platformSelect ? platformSelect.value : 'Amazon';
    if (!keyword) return;
    insertProductCard(keyword, platform);
    if (input) input.value = '';
  }

  function quickInclude(keyword, platform) {
    insertProductCard(keyword, platform);
  }

  function insertProductCard(keyword, platform) {
    var container = document.getElementById('productContainer');
    if (!container) return;

    var lower = keyword.toLowerCase();
    var img = imageCatalog.default;
    if (lower.indexOf('earbud') !== -1 || lower.indexOf('headphone') !== -1 || lower.indexOf('anc') !== -1) {
      img = imageCatalog.earbuds;
    } else if (lower.indexOf('keyboard') !== -1) {
      img = imageCatalog.keyboard;
    } else if (lower.indexOf('watch') !== -1) {
      img = imageCatalog.watch;
    } else if (lower.indexOf('monitor') !== -1 || lower.indexOf('screen') !== -1) {
      img = imageCatalog.monitor;
    } else if (lower.indexOf('power') !== -1 || lower.indexOf('charger') !== -1 || lower.indexOf('100w') !== -1) {
      img = imageCatalog.power;
    } else if (lower.indexOf('speaker') !== -1) {
      img = imageCatalog.speaker;
    }

    var isShopz = platform === 'Shopz BD';
    var affiliateUrl = isShopz
      ? 'https://www.shopz.com.bd/?s=' + encodeURIComponent(keyword) + '&post_type=product&ref=mahbubur-rahman-shahin'
      : 'https://www.amazon.com/s?k=' + encodeURIComponent(keyword) + '&tag=mrxshahin1-20&linkCode=ll2&linkId=b0640e715d1eb5bbcc6b9a28347ac557';

    var card = document.createElement('div');
    card.className = 'product-card';
    card.setAttribute('data-cat', isShopz ? 'shopz' : 'amazon');
    card.style.border = '2px solid #f59e0b';

    card.innerHTML =
      '<div class="product-img-box">' +
        '<img src="' + img + '" alt="' + keyword + '"/>' +
        '<span class="' + (isShopz ? 'shopz-badge' : 'prime-badge') + '">Visitor Choice · ' + platform + '</span>' +
      '</div>' +
      '<div class="product-category">' + (isShopz ? 'Shopz BD Tech' : 'Amazon Prime Verified') + '</div>' +
      '<h3 class="product-title">' + keyword + ' - High Performance Edition</h3>' +
      '<div class="product-rating">★★★★★ (4.9 / Newly Added)</div>' +
      '<div class="product-bottom">' +
        '<div class="product-price">$59.99</div>' +
        '<a class="' + (isShopz ? 'btn-buy-shopz' : 'btn-buy-amazon') + '" href="' + affiliateUrl + '" target="_blank" rel="noopener noreferrer">' +
          (isShopz ? 'Buy on Shopz BD' : 'Buy on Amazon') +
        '</a>' +
      '</div>';

    container.insertBefore(card, container.firstChild);
    card.scrollIntoView({ behavior: 'smooth', block: 'center' });
  }
//
